sonuclar.tahmin_sql:
SELECT order_status, COUNT(order_id) 
FROM orders 
GROUP BY order_status;

SELECT AVG(EXTRACT(EPOCH FROM (order_delivered_customer_date - order_purchase_timestamp)) / 86400) AS average_delivery_days
FROM orders
WHERE order_delivered_customer_date IS NOT NULL;

SELECT payment_type, SUM(payment_value) AS total_paid
FROM order_payments
GROUP BY payment_type;

SELECT seller_state, COUNT(*) AS seller_count
FROM sellers
GROUP BY seller_state;
